// Package api defines the JSON wire types of the vault's client-facing HTTP
// API (version 1). It is the single source of truth for the Go server, the
// Go client/CLI and the test harness; the browser client mirrors it in
// TypeScript. Endpoint semantics are specified in docs/spec/api.md.
//
// Conventions:
//   - []byte fields are encoded by encoding/json as standard base64 WITH
//     padding (RFC 4648 §4). The browser client must use the same encoding.
//   - IDs (users, vaults, items) are 32 lowercase hex characters: 16 random
//     bytes generated by the CLIENT.
//   - Times are Unix milliseconds (int64).
//   - Everything named Enc*, Wrapped* or Blob is ciphertext produced by the
//     client (docs/spec/crypto.md). The server never interprets it.
package api

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

// Error codes carried in ErrorDetail.Code. The HTTP status is given in the
// comment.
const (
	CodeBadRequest       = "bad_request"        // 400 malformed or invalid input
	CodeUnauthorized     = "unauthorized"       // 401 missing/invalid/expired token, or bad credentials
	CodeForbidden        = "forbidden"          // 403 authenticated but not allowed
	CodeNotFound         = "not_found"          // 404
	CodeVersionConflict  = "version_conflict"   // 409 base_version / base_rev / meta version does not match
	CodeKeyEpochMismatch = "key_epoch_mismatch" // 409 client is using an outdated vault key epoch
	CodeAlreadyExists    = "already_exists"     // 409 id or username already taken
	CodeInvalidInvite    = "invalid_invite"     // 403 invite unknown, used, revoked or expired
	CodeTooLarge         = "too_large"          // 413
	CodeLimitExceeded    = "limit_exceeded"     // 422 a quota (users, vaults, items) would be exceeded
	CodeRateLimited      = "rate_limited"       // 429
	CodeUnavailable      = "unavailable"        // 503 no leader / no quorum; nothing was changed
	CodeOutcomeUnknown   = "outcome_unknown"    // 503 a write was submitted but could not be confirmed; retry with the same Idempotency-Key
	CodeInternal         = "internal"           // 500
)

// ErrorBody is the body of every non-2xx response.
type ErrorBody struct {
	Error ErrorDetail `json:"error"`
}

type ErrorDetail struct {
	Code    string `json:"code"`
	Message string `json:"message"`
	// CurrentVersion is set on version_conflict for items: the item's current
	// version (0 if the item does not exist).
	CurrentVersion *uint64 `json:"current_version,omitempty"`
	// RetryAfterMs is set on rate_limited and unavailable.
	RetryAfterMs int64 `json:"retry_after_ms,omitempty"`
}

// ---------------------------------------------------------------------------
// Shared shapes
// ---------------------------------------------------------------------------

// KDFParams are the parameters of the client-side master-password KDF.
type KDFParams struct {
	Alg         string `json:"alg"` // always "argon2id"
	Salt        []byte `json:"salt"`
	Time        uint32 `json:"time"`
	MemoryKiB   uint32 `json:"memory_kib"`
	Parallelism uint8  `json:"parallelism"`
}

// WrappedKey is a vault key encrypted for one member (crypto spec §6).
type WrappedKey struct {
	SenderID string `json:"sender_id"` // user whose static key authenticated the wrap
	Blob     []byte `json:"blob"`
}

// Vault roles.
const (
	RoleOwner  = "owner"  // manage members, rename, rekey, delete; plus everything an editor can do
	RoleEditor = "editor" // create/update/delete items
	RoleViewer = "viewer" // read only
)

// ---------------------------------------------------------------------------
// Public endpoints
// ---------------------------------------------------------------------------

// GET /v1/health
type HealthResponse struct {
	NodeID       string `json:"node_id"`
	Role         string `json:"role"` // follower | pre-candidate | candidate | leader
	LeaderID     string `json:"leader_id"`
	Term         uint64 `json:"term"`
	CommitIndex  uint64 `json:"commit_index"`
	AppliedIndex uint64 `json:"applied_index"`
	Initialized  bool   `json:"initialized"` // cluster key exists (first leader has bootstrapped state)
	HasUsers     bool   `json:"has_users"`   // false => the next registration must use the bootstrap token
	Version      string `json:"version"`
}

// GET /v1/cluster
type ClusterResponse struct {
	Nodes    []ClusterNode `json:"nodes"`
	LeaderID string        `json:"leader_id"`
}

type ClusterNode struct {
	ID        string `json:"id"`
	PublicURL string `json:"public_url"` // base URL of the node's client API
}

// POST /v1/prelogin
type PreloginRequest struct {
	Username string `json:"username"`
}

type PreloginResponse struct {
	KDF KDFParams `json:"kdf"`
}

// POST /v1/register
type RegisterRequest struct {
	InviteCode        string             `json:"invite_code"` // an invite code, or the bootstrap token for the very first user
	UserID            string             `json:"user_id"`
	Username          string             `json:"username"`
	KDF               KDFParams          `json:"kdf"`
	LoginKey          []byte             `json:"login_key"`  // 32 bytes; the server stores only a salted hash
	PublicKey         []byte             `json:"public_key"` // X25519, 32 bytes
	WrappedAccountKey []byte             `json:"wrapped_account_key"`
	EncPrivateKey     []byte             `json:"enc_private_key"`
	PersonalVault     CreateVaultRequest `json:"personal_vault"`
}

// POST /v1/login
type LoginRequest struct {
	Username string `json:"username"`
	LoginKey []byte `json:"login_key"`
}

// LoginResponse is returned by register, login and password change.
type LoginResponse struct {
	Token     string `json:"token"`
	ExpiresAt int64  `json:"expires_at"`
	UserID    string `json:"user_id"`
	Username  string `json:"username"`
	IsAdmin   bool   `json:"is_admin"`
}

// ---------------------------------------------------------------------------
// Sync (authenticated)
// ---------------------------------------------------------------------------

// GET /v1/sync[?since=<rev>][&consistency=stale]
//
// The response is the complete state visible to the caller. Clients persist
// it verbatim as their offline cache.
type SyncResponse struct {
	Rev       uint64 `json:"rev"`                 // global revision of the replicated state
	Unchanged bool   `json:"unchanged,omitempty"` // since == rev: nothing else is populated
	Stale     bool   `json:"stale,omitempty"`     // served from local state without quorum confirmation
	ServedBy  string `json:"served_by,omitempty"` // node id

	Account   *Account        `json:"account,omitempty"`
	Directory []DirectoryUser `json:"directory,omitempty"` // every household member, including the caller
	Vaults    []Vault         `json:"vaults,omitempty"`    // sorted by id
}

type Account struct {
	UserID            string    `json:"user_id"`
	Username          string    `json:"username"`
	IsAdmin           bool      `json:"is_admin"`
	KDF               KDFParams `json:"kdf"`
	PublicKey         []byte    `json:"public_key"`
	WrappedAccountKey []byte    `json:"wrapped_account_key"`
	EncPrivateKey     []byte    `json:"enc_private_key"`
	CreatedAt         int64     `json:"created_at"`
}

type DirectoryUser struct {
	UserID    string `json:"user_id"`
	Username  string `json:"username"`
	PublicKey []byte `json:"public_key"`
	IsAdmin   bool   `json:"is_admin"`
	Disabled  bool   `json:"disabled"`
}

type Vault struct {
	ID               string     `json:"id"`
	Personal         bool       `json:"personal"`
	KeyEpoch         uint32     `json:"key_epoch"`         // starts at 1, +1 on every rekey
	EncMeta          []byte     `json:"enc_meta"`          // encrypted vault metadata (name)
	MetaVersion      uint64     `json:"meta_version"`      // CAS token for enc_meta
	EncRoster        []byte     `json:"enc_roster"`        // member list sealed under the vault key (crypto spec §6.3)
	RosterVersion    uint64     `json:"roster_version"`    // CAS token for enc_roster
	Rev              uint64     `json:"rev"`               // global rev of the last change to anything in this vault
	RekeyRecommended bool       `json:"rekey_recommended"` // a member was removed since the last rekey
	MyRole           string     `json:"my_role"`
	MyKey            WrappedKey `json:"my_key"`
	Members          []Member   `json:"members"` // sorted by user id
	Items            []Item     `json:"items"`   // sorted by id
}

type Member struct {
	UserID  string `json:"user_id"`
	Role    string `json:"role"`
	AddedBy string `json:"added_by"`
}

type Item struct {
	ID        string `json:"id"`
	Version   uint64 `json:"version"` // global rev at which this item was last written; never reused
	Blob      []byte `json:"blob"`
	UpdatedAt int64  `json:"updated_at"`
	UpdatedBy string `json:"updated_by"`
}

// ---------------------------------------------------------------------------
// Account (authenticated)
// ---------------------------------------------------------------------------

// POST /v1/account/password -> LoginResponse (all older tokens are revoked)
type ChangePasswordRequest struct {
	CurrentLoginKey      []byte    `json:"current_login_key"`
	NewKDF               KDFParams `json:"new_kdf"`
	NewLoginKey          []byte    `json:"new_login_key"`
	NewWrappedAccountKey []byte    `json:"new_wrapped_account_key"`
}

// POST /v1/account/revoke-sessions -> LoginResponse (a fresh token; all older tokens are revoked)

// ---------------------------------------------------------------------------
// Vaults, members, items (authenticated)
// ---------------------------------------------------------------------------

// POST /v1/vaults -> MutationResponse
type CreateVaultRequest struct {
	VaultID    string     `json:"vault_id"`
	EncMeta    []byte     `json:"enc_meta"`
	EncRoster  []byte     `json:"enc_roster"`  // the first roster: the creator as sole owner
	WrappedKey WrappedKey `json:"wrapped_key"` // the vault key wrapped for the creator (sender_id == creator)
}

// PUT /v1/vaults/{vault}/meta -> MutationResponse
type UpdateVaultMetaRequest struct {
	EncMeta         []byte `json:"enc_meta"`
	BaseMetaVersion uint64 `json:"base_meta_version"`
}

// DELETE /v1/vaults/{vault} -> MutationResponse

// PUT /v1/vaults/{vault}/members/{user} -> MutationResponse
// Adds a member (wrapped_key required) or changes an existing member's role
// (wrapped_key omitted). Either way the caller uploads the new roster, which
// replaces the stored one iff base_roster_version matches.
type PutMemberRequest struct {
	Role              string      `json:"role"`
	WrappedKey        *WrappedKey `json:"wrapped_key,omitempty"`
	KeyEpoch          uint32      `json:"key_epoch"` // epoch of the vault key in use; must be the vault's current epoch
	EncRoster         []byte      `json:"enc_roster"`
	BaseRosterVersion uint64      `json:"base_roster_version"`
}

// DELETE /v1/vaults/{vault}/members/{user} -> MutationResponse
// A member leaving on their own, or an owner cutting off a member's access
// immediately without a rekey. The roster is untouched and rekey_recommended
// is set. Owners normally remove members through rekey (RekeyRequest.Remove),
// which is atomic.

// POST /v1/vaults/{vault}/rekey -> MutationResponse
// Atomically replaces the vault key: optionally removes members, then installs
// new metadata, a new roster, a wrapped key for every remaining member and
// every item re-encrypted under the new key.
type RekeyRequest struct {
	BaseRev     uint64                `json:"base_rev"`         // the vault's rev the client based the rekey on
	NewKeyEpoch uint32                `json:"new_key_epoch"`    // must be current epoch + 1
	Remove      []string              `json:"remove,omitempty"` // members removed by this rekey (current members; never the caller)
	EncMeta     []byte                `json:"enc_meta"`
	EncRoster   []byte                `json:"enc_roster"`
	WrappedKeys map[string]WrappedKey `json:"wrapped_keys"` // exactly the current member set minus Remove, keyed by user id
	Items       []RekeyItem           `json:"items"`        // exactly the current item set
}

type RekeyItem struct {
	ID   string `json:"id"`
	Blob []byte `json:"blob"`
}

// PUT /v1/vaults/{vault}/items/{item} -> MutationResponse
type PutItemRequest struct {
	Blob        []byte `json:"blob"`
	BaseVersion uint64 `json:"base_version"` // 0 = create (item must not exist); otherwise must equal the current version
	KeyEpoch    uint32 `json:"key_epoch"`    // must be the vault's current epoch
}

// DELETE /v1/vaults/{vault}/items/{item}?base_version=N -> MutationResponse

// MutationResponse is returned by every successful vault/member/item write.
type MutationResponse struct {
	Rev     uint64 `json:"rev"`               // global rev after the write
	Version uint64 `json:"version,omitempty"` // items: the item's new version (== rev); meta: the new meta_version
}

// ---------------------------------------------------------------------------
// Household administration (authenticated, admin only)
// ---------------------------------------------------------------------------

// POST /v1/invites
type CreateInviteRequest struct {
	TTLHours int `json:"ttl_hours"` // 0 = default (72); max 720
}

type CreateInviteResponse struct {
	InviteID  string `json:"invite_id"`
	Code      string `json:"code"` // shown once; the server keeps only its hash
	ExpiresAt int64  `json:"expires_at"`
}

// GET /v1/invites
type ListInvitesResponse struct {
	Invites []Invite `json:"invites"`
}

type Invite struct {
	InviteID  string `json:"invite_id"`
	CreatedBy string `json:"created_by"`
	CreatedAt int64  `json:"created_at"`
	ExpiresAt int64  `json:"expires_at"`
	UsedBy    string `json:"used_by,omitempty"` // user id, once consumed
}

// DELETE /v1/invites/{invite_id} -> MutationResponse

// PUT /v1/admin/users/{user} -> MutationResponse
// Fields that are nil are left unchanged.
type AdminUpdateUserRequest struct {
	Disabled *bool `json:"disabled,omitempty"`
	IsAdmin  *bool `json:"is_admin,omitempty"`
}

// GET /v1/admin/cluster
type AdminClusterResponse struct {
	NodeID        string            `json:"node_id"`
	Role          string            `json:"role"`
	LeaderID      string            `json:"leader_id"`
	Term          uint64            `json:"term"`
	CommitIndex   uint64            `json:"commit_index"`
	AppliedIndex  uint64            `json:"applied_index"`
	LastLogIndex  uint64            `json:"last_log_index"`
	SnapshotIndex uint64            `json:"snapshot_index"`
	Rev           uint64            `json:"rev"`
	Peers         []AdminPeerStatus `json:"peers,omitempty"` // leader only
}

type AdminPeerStatus struct {
	ID            string `json:"id"`
	MatchIndex    uint64 `json:"match_index"`
	LastContactMs int64  `json:"last_contact_ms"` // milliseconds since last contact; -1 if never
}

// GET /v1/admin/backup -> ServerBackup
// A dump of the whole replicated state except the token-signing key: all
// ciphertext plus every user's password verifier, KDF salt, wrapped account
// key and encrypted private key, the membership graph and invite hashes. It
// never contains plaintext secrets, but it is everything needed for offline
// guessing of master passwords, so it is as sensitive as a server's disk.
// `vaultd restore` seeds a fresh cluster from it.
type ServerBackup struct {
	Format    string `json:"format"` // "fpv-server-backup"
	Version   int    `json:"version"`
	CreatedAt int64  `json:"created_at"`
	NodeID    string `json:"node_id"`
	Rev       uint64 `json:"rev"`
	State     []byte `json:"state"` // a StateMachine snapshot
}
